      if (!trimmed) continue; // 元数据区的空行忽略，不算正文开始
      const mm = META_RE.exec(trimmed);
      const key = mm ? KEY_ALIAS.get(mm[1].toLowerCase()) : undefined;
      if (mm && key && META_KEYS.has(key)) {
