  const seen = new Map();
  for (const b of out) {
    if (b.order === null || !Number.isFinite(b.order)) {
      b.order = b.type === "system" ? DEFAULT_SYSTEM_ORDER : DEFAULT_CONTEXT_ORDER;
    }
    const base = `${b.type}:${b.title || "untitled"}`;
    const n = (seen.get(base) || 0) + 1;
    seen.set(base, n);
    b.id = n === 1 ? base : `${base}#${n}`;
