/**
 * 把块数组序列化回数据文件文本。
 * @param blocks - 块数组。
 * @returns 文件全文（带说明头）。
 */
export function serializeBlocks(blocks) {
  const head = [
    "# @gw/dsh-text-inject — 文字注入配置",
    "#",
    "# 块头写法：## [system] 标题   或   ## [context] 标题",
    "# 可选元数据行（写在块头下方，正文之前）：",
    "#   描述: 一句话说明（只有你看，不进提示词）",
    "#   排序: 数字，决定拼在提示词里的位置；系统侧默认 40，上下文侧默认 125",
