    "#",
    "# 这个文件由设置页「文字注入」维护，也可以直接手改（保存即热加载）。",
    "",
  ].join("\n");

  const parts = [];
  for (const b of Array.isArray(blocks) ? blocks : []) {
    if (!b || (b.type !== "system" && b.type !== "context")) continue;
    const type = b.type;
    const title = String(b.title || "").trim() || "未命名";
